import { useState } from 'react';

/**
 * Test stand-in for `virtual:pwa-register/react` (generated by vite-plugin-pwa at
 * build time). Tests set `pwaStub.offlineReady` / `pwaStub.needRefresh` before render
 * and read `pwaStub.updateCalls` afterwards.
 */
export const pwaStub = {
  offlineReady: false,
  needRefresh: false,
  updateCalls: [] as boolean[],
  reset() {
    this.offlineReady = false;
    this.needRefresh = false;
    this.updateCalls = [];
  },
};

export function useRegisterSW() {
  const offlineReady = useState(pwaStub.offlineReady);
  const needRefresh = useState(pwaStub.needRefresh);
  return {
    offlineReady,
    needRefresh,
    updateServiceWorker: (reload?: boolean) => {
      pwaStub.updateCalls.push(reload ?? false);
      return Promise.resolve();
    },
  };
}
